/**
 * Builds the text-only handoff brief for Codex / Claude Code. Pure function so
 * it can be unit-tested and reused by the editor dock, the handoff dialog and
 * the project overview.
 */
import type { DemoAsset, DemoProject, DemoRevision } from '../types';
import { framesToTimecode } from './timecode';

export type AgentClient = 'codex' | 'claude-code';

export const AGENT_CLIENT_LABEL: Record<AgentClient, string> = {
  codex: 'Codex',
  'claude-code': 'Claude Code',
};

export const DEMO_DISCLAIMER =
  '[DEMO MODE] Generated by the AgenEditor UI prototype. The MCP server is not connected; no tools listed below can run yet. All IDs refer to demo fixture data.';

export function buildAgentBrief(input: {
  project: DemoProject;
  assets: DemoAsset[];
  revision: DemoRevision | null;
  client: AgentClient;
}): string {
  const { project, assets, revision, client } = input;
  const fps = project.fpsNum / project.fpsDen;
  const seconds = (project.targetDurationFrames / fps).toFixed(1);
  const assetLines = assets.length
    ? assets.map((a) => `  - ${a.id} [${a.kind}] ${a.filename}`).join('\n')
    : '  - (no assets attached)';
  const revLine = revision
    ? `Current revision: v${revision.revisionNumber} (${revision.id}), ${framesToTimecode(revision.durationFrames, fps)} long, ${revision.tracks.reduce((n, t) => n + t.clips.length, 0)} clips`
    : 'Current revision: none yet';

  return [
    DEMO_DISCLAIMER,
    '',
    `AgenEditor editing handoff for ${AGENT_CLIENT_LABEL[client]}`,
    '',
    `Project: ${project.name} (${project.id})`,
    `Output: ${project.width}x${project.height}, ${fps} fps, target ${seconds} s (${project.targetDurationFrames} frames)`,
    revLine,
    '',
    'Editing brief:',
    project.brief || '(empty)',
    '',
    'Source assets (user-supplied only):',
    assetLines,
    '',
    'Planned MCP tools (unavailable in the UI prototype):',
    '  - list_assets, inspect_asset, get_transcript',
    '  - submit_edit_plan, validate_timeline, commit_timeline (expected_revision required)',
    '  - start_preview_render, get_job_status, run_qa',
    'Cite source asset IDs and frame ranges for every cut; never invent timestamps or quotes.',
    '',
    'Rules: edit only the user-supplied media above. Do not generate video, images, voices or music yourself;',
    'request missing visuals as asset_requests so the user can generate them externally and import them.',
  ].join('\n');
}

/** Copies text; resolves false when the clipboard API is unavailable. */
export async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    return false;
  }
}
